/**
 * FalconCut brand mark — the real artwork (golden eagle on a blue/orange rounded
 * tile), rendered from /logo-mark.png (128px, generated by scripts/make-icons.mjs
 * from the designer's SVG). The same asset backs the favicon, the PWA icons and
 * the Windows .ico, so the brand is identical everywhere.
 *
 * Kept as a component so the boundary stays stable: swap the image (or point it
 * at a vector export) without touching every call site.
 */
export function LogoMark({ size = 20, title = 'FalconCut' }: { size?: number; title?: string }) {
  return (
    <img
      src="/logo-mark.png"
      width={size}
      height={size}
      alt={title}
      draggable={false}
      decoding="async"
      className="shrink-0 select-none rounded-[22%] shadow-[0_1px_4px_rgba(0,0,0,0.45)]"
      style={{ width: size, height: size }}
    />
  );
}
